const { NOTE_STATUS } = require("@/utils/patterns/product-patterns");
const { generatePublicId } = require("@/utils/generate-public-id");
const {
  enqueueNoteEmbeddingJob,
} = require("../../../services/queue/queue-controller");

const DEFAULT_NOTE_PROPERTIES = {
  banner: { name: "", path: "", type: "" },
  color: "",
  files: [],
  icon: { name: "", path: "", type: "" },
  relations: [],
  urls: [],
};

/**
 * Criação de notas.
 */
class CreateNotesRepository extends BaseRepository {
  async createNotesQuery(
    userId,
    title,
    content,
    tags = [],
    status = NOTE_STATUS.VISIBLE,
    projectId = null,
    priorityId = null,
    assignedTo = null
  ) {
    const query = `
      INSERT INTO notes (
        user_id,
        title,
        description,
        tags,
        status,
        project_id,
        properties,
        priority_id,
        public_note_id
      )
      VALUES ($1, $2, $3, $4::uuid[], $5, $6, $7, $8, $9)
      RETURNING *; 
    `;
    const results = await this.executeQuery(query, [
      userId,
      title,
      content,
      tags,
      status,
      projectId,
      JSON.stringify(DEFAULT_NOTE_PROPERTIES),
