    if (createdNote) {
      await enqueueNoteEmbeddingJob(createdNote.id).catch((err) => {
        console.error(
          "[CreateNotesRepository] Failed to enqueue embedding job",
          err
        );
      });
    }

    return createdNote;
  }

  async createCompleteNote(
    userId,
    title,
    description,
    tags = [],
    initialBlockContent = "",
    status = NOTE_STATUS.VISIBLE,
    projectId = null
  ) {
    const query = `
      WITH new_note AS (
        INSERT INTO notes (
          user_id,
          title,
          description,
          tags,
          status,
          project_id,
          properties,
          public_note_id
        )
        VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
        RETURNING *
      )
      SELECT 
        new_note.id AS note_id,
        new_note.public_note_id,
        new_note.project_id,
        new_note.title,
        new_note.description,
        new_note.properties,
        new_note.tags,
        new_note.status,
        new_note.created_at AS note_created_at,
        new_note.updated_at AS note_updated_at,
        new_note.user_id,

        u.name AS user_name,
        u.username AS user_username,
        u.email AS user_email,
        u.avatar_url AS user_avatar_url
      FROM new_note
      INNER JOIN users u ON new_note.user_id = u.user_id
      LIMIT 1;
    `;
    const results = await this.executeQuery(query, [
      userId,
      title,
      description,
      tags,
      status,
      projectId,
      JSON.stringify(DEFAULT_NOTE_PROPERTIES),
      generatePublicId(),
    ]);
    const createdNote = results[0];

    console.log("[CreateNotesRepository] Note created", {
      noteId: createdNote?.note_id,
    });

    if (createdNote) {
      console.log(
        "[CreateNotesRepository] Enqueueing embedding job for",
        createdNote.note_id
      );
      await enqueueNoteEmbeddingJob(createdNote.note_id).catch((err) => {
        console.error(
          "[CreateNotesRepository] Failed to enqueue embedding job",
          err
        );
      });
    }

    return createdNote;
  }
}

module.exports = new CreateNotesRepository();

const BaseRepository = require("./base.repository");
const {
  enqueueNoteEmbeddingJob,
} = require("../../../services/queue/queue-controller");
const {
  buildNoteIdWhereClause,
  buildNotesBulkDeleteWhere,
} = require("@/utils/note-id-lookup");

/**
 * Atualização e exclusão lógica de notas.
 */
class MutateNotesRepository extends BaseRepository {
  async updateNoteById(noteId, updateData, baseRevision = null) {
    const allowedFields = [
      "title",
      "description",
      "tags",
      "status",
      "priority_id",
      "due_date",
      "deleted_by",
      "deleted",
      "project_id",
      "project_stage_id",
      "parent_id",
      "properties",
    ];

    const updates = [];
    const values = [];
    let paramIndex = 1;

    allowedFields.forEach((field) => {
      if (updateData[field] !== undefined) {
        if (field === "properties") {
          updates.push(
            `properties = COALESCE(properties, '{}'::jsonb) || $${paramIndex}::jsonb`
          );
          values.push(JSON.stringify(updateData[field]));
        } else {
          updates.push(`${field} = $${paramIndex}`);
          values.push(updateData[field]);
        }
        paramIndex++;
      }
    });

    if (updates.length === 0) {
      return null;
    }

    updates.push("updated_at = NOW()");
    updates.push("revision = revision + 1");

    values.push(noteId);
    if (baseRevision !== null && baseRevision !== undefined) {
      values.push(Number(baseRevision));
    }

    const noteIdWhere = buildNoteIdWhereClause("notes", paramIndex, noteId);
    const whereClause =
      baseRevision !== null && baseRevision !== undefined
        ? `${noteIdWhere} AND revision = $${paramIndex + 1}`
        : noteIdWhere;

    const query = `
      UPDATE notes
      SET ${updates.join(", ")}
      WHERE ${whereClause}
      RETURNING *;
    `;

    const results = await this.executeQuery(query, values);
    const updatedNote = results[0];

    console.log("[MutateNotesRepository] Note updated", {
      noteId: updatedNote?.id,
    });

    if (updatedNote) {
      console.log(
        "[MutateNotesRepository] Enqueueing embedding job for",
        updatedNote.id
      );
      await enqueueNoteEmbeddingJob(updatedNote.id).catch((err) => {
        console.error(
          "[MutateNotesRepository] Failed to enqueue embedding job",
          err
        );
      });
    }

    return updatedNote;
  }

  async bumpRevisionById(noteId, baseRevision = null) {
    const values = [noteId];
    let revisionFilter = "";
    let revisionParamIndex = 2;
    if (baseRevision !== null && baseRevision !== undefined) {
      values.push(Number(baseRevision));
      revisionFilter = `AND revision = $${revisionParamIndex}`;
      revisionParamIndex += 1;
    }

    const noteIdWhere = buildNoteIdWhereClause("notes", 1, noteId);

    const query = `
      UPDATE notes
      SET revision = revision + 1, updated_at = NOW()
      WHERE ${noteIdWhere}
      ${revisionFilter}
      RETURNING id, revision, updated_at
    `;
    const results = await this.executeQuery(query, values);
    return results[0] || null;
  }

  async deleteNoteById(noteIds) {
    const idsArray = Array.isArray(noteIds) ? noteIds : [noteIds];
    const { sql: whereSql, params } = buildNotesBulkDeleteWhere(idsArray);

    const query = `
    UPDATE notes
    SET deleted = true
    WHERE ${whereSql};
  `;

    const result = await this.executeQuery(query, params);

    if (result.rowCount === 0) {
      throw new Error("Nenhuma nota encontrada para deleção.");
    }

    return result.rowCount;
  }
}

module.exports = new MutateNotesRepository();

const ROLE_LABELS = {
  admin: "admin",
  guest: "guest",
  member: "member",
  super_admin: "super admin",
  viewer: "viewer",
};

const RESERVED_CONTEXT_KEYS = new Set([
  "message",
  "summary",
  "description",
  "preview",
]);

const ensureObject = (value) => {
  if (!value) {
    return {};
  }

  if (typeof value === "object") {
    return value;
  }

  if (typeof value === "string") {
    try {
      return JSON.parse(value);
    } catch (error) {
      return {};
    }
  }

  return {};
};

const sanitizeValue = (value) => {
  if (value === undefined) {
    return undefined;
  }

  if (value === null) {
    return null;
  }

  if (value instanceof Date) {
    return value.toISOString();
  }

  if (typeof value === "bigint") {
    return value.toString();
  }

  if (Array.isArray(value)) {
    return value
      .map((item) => sanitizeValue(item))
      .filter((item) => item !== undefined);
  }

  if (typeof value === "object") {
    return Object.entries(value).reduce((acc, [key, nestedValue]) => {
      const sanitized = sanitizeValue(nestedValue);
      if (sanitized !== undefined) {
        acc[key] = sanitized;
      }
      return acc;
    }, {});
  }

  return value;
};

const sanitizeContext = (source) => {
  if (!source || typeof source !== "object") {
    return {};
  }

  return Object.entries(source).reduce((acc, [key, value]) => {
    if (RESERVED_CONTEXT_KEYS.has(key) || key === "action") {
      return acc;
    }

    const sanitized = sanitizeValue(value);
    if (sanitized !== undefined) {
      acc[key] = sanitized;
    }

    return acc;
  }, {});
};

const formatRole = (role) => {
  if (!role || typeof role !== "string") {
    return null;
  }

  const normalized = role.toLowerCase();
  return ROLE_LABELS[normalized] || normalized;
};

const cleanSentence = (text) => {
  if (!text) {
    return "";
  }

  return String(text).replace(/\s+/g, " ").trim();
};

const formatDateTime = (value) => {
  if (!value) {
    return null;
  }

  const date = value instanceof Date ? value : new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
};

const buildContentKey = (type, actionKey) => {
  const normalizedType = type || "notification";
  const normalizedAction = actionKey || "generic";

  return `${normalizedType}.${normalizedAction}`;
};

const createBaseContent = (payload, options = {}) => {
  const rawContent = ensureObject(payload.content);
  const rawActionKey = rawContent.action;

  const actionKey = options.actionKey || rawActionKey || null;
  const sanitizedContext = sanitizeContext(rawContent);
  const extraContext = sanitizeContext(options.contextExtras || {});
  const context = { ...sanitizedContext, ...extraContext };

  if (actionKey && !context.event_key) {
    context.event_key = actionKey;
  }

  const resolvedMessage =
    cleanSentence(options.message) ||
    cleanSentence(rawContent.message) ||
    payload.title ||
    "You have a new notification.";

  const resolvedSummary =
    cleanSentence(options.summary) ||
    cleanSentence(rawContent.summary) ||
    resolvedMessage;

  const resolvedDescription =
    cleanSentence(options.description) ||
    cleanSentence(rawContent.description) ||
    resolvedSummary;

  const normalizedContent = {
    action: options.actionText || null,
    description: resolvedDescription,
    key: buildContentKey(payload.type, actionKey),
    message: resolvedMessage,
    preview: cleanSentence(rawContent.preview) || resolvedSummary,
    summary: resolvedSummary,
  };

  const resolvedUrl = options.url || rawContent.url;
  if (resolvedUrl) {
    normalizedContent.url = resolvedUrl;
  }

  const entityName =
    options.entityName ||
    rawContent.entity_name ||
    rawContent.organization_name ||
    rawContent.project_title ||
    rawContent.note_title ||
    null;

  if (payload.entityType || payload.entityId || entityName) {
    normalizedContent.entity = {
      id: payload.entityId || null,
      name: entityName,
      type: payload.entityType || null,
    };
  }

  if (Object.keys(context).length > 0) {
    normalizedContent.context = context;
  }

  return normalizedContent;
};

const buildOrganizationActionContent = (payload) => {
  const actionKey = payload.content?.action;
  const organizationName = payload.content?.organization_name;
  const roleLabel = formatRole(payload.content?.role);

  if (actionKey === "member_added") {
    const message =
      payload.content?.message ||
      `You have been added to the organization ${
        organizationName || "Weave Notes"
      }${roleLabel ? ` as ${roleLabel}` : ""}.`;

    return createBaseContent(payload, {
      actionKey,
      entityName: organizationName,
      message,
    });
  }

  return null;
};

const buildOrganizationInviteContent = (payload) => {
  const actionKey = payload.content?.action;
  const organizationName = payload.content?.organization_name;
  const roleLabel = formatRole(payload.content?.role);

  if (actionKey === "invite_sent") {
    const inviterName = payload.content?.inviter_name;
    const message =
      payload.content?.message ||
      `${inviterName || "A member"} invited you to the organization ${
        organizationName || "Weave Notes"
      }${roleLabel ? ` as ${roleLabel}` : ""}.`;

    return createBaseContent(payload, {
      actionKey,
      actionText: "Access your organizations to accept or decline the invite.",
      entityName: organizationName,
      message,
    });
  }

  if (actionKey === "invite_accepted") {
    const newMemberName = payload.content?.new_member_name;
    const message =
      payload.content?.message ||
      `${newMemberName || "A new member"} accepted your invite and is now part of the organization ${organizationName || "Weave Notes"}.`;

    return createBaseContent(payload, {
      actionKey,
      entityName: organizationName,
      message,
    });
  }

  return null;
};

const buildProjectInviteContent = (payload) => {
  const actionKey = payload.content?.action;
  const projectTitle = payload.content?.project_title;
  const roleLabel = formatRole(payload.content?.role);

  if (actionKey === "collaborator_added") {
    const message =
      payload.content?.message ||
      `You have been added to the project ${projectTitle || "untitled"}${
        roleLabel ? ` as ${roleLabel}` : ""
      }.`;

    return createBaseContent(payload, {
      actionKey,
      actionText: "Open the project to start collaborating.",
      entityName: projectTitle,
      message,
    });
  }

  return null;
};

const buildProjectActionContent = (payload) => {
  const actionKey = payload.content?.action;
  const projectTitle = payload.content?.project_title;
  const roleLabel = formatRole(payload.content?.role);

  if (actionKey === "collaborator_updated") {
    const message =
      payload.content?.message ||
      `Your permission in the project ${projectTitle || "untitled"} was updated to ${roleLabel || "a new role"}.`;

    return createBaseContent(payload, {
      actionKey,
      entityName: projectTitle,
      message,
    });
  }

  return null;
};

const buildNoteSharedContent = (payload) => {
  const actionKey = payload.content?.action;
  const noteTitle = payload.content?.note_title;

  if (actionKey === "collaborator_added") {
    const sharedByName = payload.content?.shared_by_name;
    const message =
      payload.content?.message ||
      `${sharedByName || "The owner"} shared the note ${noteTitle || "untitled"} with you.`;

    return createBaseContent(payload, {
      actionKey,
      actionText: "Open the note and start collaborating.",
      entityName: noteTitle,
      message,
    });
  }

  return null;
};

const buildJobActionContent = (payload) => {
  const actionKey = payload.content?.action;

  if (actionKey === "backup_completed") {
    const expiresAt = payload.content?.expires_at;
    const formattedExpiration = formatDateTime(expiresAt);
    const baseMessage = "Your backup is ready for download.";
    const message =
      payload.content?.message ||
      `${baseMessage}${formattedExpiration ? ` The link expires at ${formattedExpiration}.` : ""}`;

    return createBaseContent(payload, {
      actionKey,
      actionText: "Download the backup within 48 hours to avoid expiration.",
      entityName: payload.content?.job_name || null,
      message,
      url: payload.content?.download_url,
    });
  }

  return null;
};

const builders = {
  job_action: buildJobActionContent,
  note_shared: buildNoteSharedContent,
  organization_action: buildOrganizationActionContent,
  organization_invite: buildOrganizationInviteContent,
  project_action: buildProjectActionContent,
  project_invite: buildProjectInviteContent,
};

const defaultBuilder = (payload) => createBaseContent(payload);

const normalizeNotificationPayload = (payload = {}) => {
  const safePayload = {
    ...payload,
    title:
      typeof payload.title === "string" && payload.title.trim().length > 0
        ? payload.title.trim()
        : "Notification",
  };

  safePayload.content = ensureObject(payload.content);

  const builder = builders[safePayload.type];
  const normalizedContent = builder
    ? builder(safePayload) || defaultBuilder(safePayload)
    : defaultBuilder(safePayload);

  return {
    ...payload,
    content: normalizedContent,
    title: safePayload.title,
  };
};

module.exports = {
  normalizeNotificationPayload,
};

const { fromUnknown } = require("@/errors");
const OrganizationsBaseController = require("./base-controller");
const areasRepository = require("@/modules/organizations/repositories/areas.repository");
const SearchUsersRepository = require("@/modules/users/repositories/search-users.repository");
const { normalizeOrganizationName } = require("../normalizer");
const {
  ORG_ROLES,
} = require("@/modules/organizations/organization-role-policy");

const AREA_MEMBER_ROLES = [ORG_ROLES.ADMIN, ORG_ROLES.MEMBER, ORG_ROLES.GUEST];

class OrganizationAreasController extends OrganizationsBaseController {
  constructor() {
    super();
    this.areasRepository = areasRepository;
  }

  /** Role in `organization_members` (aligned with permission engine). */
  _canManageOrgStructure(organization) {
    return this._orgRoleHasPermission(
      organization,
      this._orgPermissions.MANAGE_AREAS
    );
  }

  async _userIsAreaManager(organization, areaId, userId) {
    const member = await this.areasRepository.getAreaMember(
      areaId,
      organization.id,
      userId
    );
    return member?.role === ORG_ROLES.ADMIN;
  }

  /**
   * Admin/super_admin with MANAGE_AREAS or area manager.
   * @returns {Promise<boolean>}
   */
  async _requireAreaWriteAccess(res, organization, areaId, userId) {
    if (this._canManageOrgStructure(organization)) return true;
    if (await this._userIsAreaManager(organization, areaId, userId)) {
      return true;
    }
    res.status(403).json({
      error:
        "Insufficient permissions. Organization administrator or area manager required.",
      success: false,
    });
    return false;
  }

  _normalizeSlug(areaName, providedSlug) {
    const baseValue = providedSlug?.trim() || areaName?.trim();
    if (!baseValue) {
      return null;
    }

    return normalizeOrganizationName(baseValue);
  }

  async _ensureUniqueSlug(organizationId, slug, currentSlug = null) {
    const existing = await this.areasRepository.getMatchingSlugs(
      organizationId,
      slug
    );

    const filtered = currentSlug
      ? existing.filter((value) => value !== currentSlug)
      : existing;

    if (!filtered.includes(slug)) {
      return slug;
    }

    let counter = 1;
    let candidate = `${slug}-${counter}`;
    while (filtered.includes(candidate)) {
      counter += 1;
      candidate = `${slug}-${counter}`;
    }
    return candidate;
  }

  _ensurePropertiesShape(properties) {
    if (properties === undefined) return undefined;
    if (properties === null) return {};
    if (typeof properties !== "object" || Array.isArray(properties)) {
      throw new Error("properties deve ser um objeto");
    }
    return properties;
  }

  async _getParentArea(organizationId, parentAreaId) {
    if (!parentAreaId) return null;
    const parent = await this.areasRepository.getAreaById(
      parentAreaId,
      organizationId
    );
    if (!parent) {
      throw new Error("Parent area not found");
    }
    return parent;
  }

  async listAreas(req, res, next) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const organization = await this._getUserOrganization(userId);
      if (!organization) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      const areas = await this.areasRepository.listOrganizationAreas(
        organization.id
      );

      res.status(200).json({
        count: areas.length,
        data: areas,
        organization_id: organization.id,
        status: "OK",
      });
    } catch (error) {
      console.error("Error listing areas:", error);
      return next(fromUnknown(error));
    }
  }

  async getArea(req, res, next) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const organization = await this._getUserOrganization(userId);
      if (!organization) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      const { areaId } = req.params;
      const area = await this.areasRepository.getAreaById(
        areaId,
        organization.id
      );

      if (!area) {
        return res
          .status(404)
          .json({ error: "Area not found", success: false });
      }

      res.status(200).json({ data: area, status: "OK" });
    } catch (error) {
      console.error("Error fetching area:", error);
      return next(fromUnknown(error));
    }
  }

  async createArea(req, res, next) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const organization = await this._getUserOrganization(userId);
      if (!organization) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      const {
        area_name,
        parent_area_id = null,
        slug,
        description,
        properties,
      } = req.body;

      const isSubArea = parent_area_id !== null && parent_area_id !== undefined;
      const canOrgStructure = this._canManageOrgStructure(organization);

      if (!isSubArea && !canOrgStructure) {
        return res.status(403).json({
          error: "Only organization administrators can create root areas",
          success: false,
        });
      }

      if (isSubArea) {
        await this._getParentArea(organization.id, parent_area_id);

        if (!canOrgStructure) {
          const member = await this.areasRepository.getAreaMember(
            parent_area_id,
            organization.id,
            userId
          );

          if (!member || member.role !== ORG_ROLES.ADMIN) {
            return res.status(403).json({
              error: "Only area admins of the parent area can create sub-areas",
              success: false,
            });
          }
        }
      }

      const normalizedSlug = this._normalizeSlug(area_name, slug);
      if (!normalizedSlug) {
        return res
          .status(400)
          .json({ error: "Invalid area slug", success: false });
      }

      const uniqueSlug = await this._ensureUniqueSlug(
        organization.id,
        normalizedSlug
      );

      const normalizedProperties =
        this._ensurePropertiesShape(properties) || {};

      const newArea = await this.areasRepository.createArea({
        areaName: area_name.trim(),
        createdBy: userId,
        description: description?.trim() || "Area description here",
        organizationId: organization.id,
        parentAreaId: parent_area_id || null,
        properties: normalizedProperties,
        slug: uniqueSlug,
      });

      res.status(201).json({
        data: newArea,
        message: "Area created successfully",
        status: "OK",
      });
    } catch (error) {
      console.error("Error creating area:", error);
      return next(fromUnknown(error));
    }
  }

  async updateArea(req, res, next) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const organization = await this._getUserOrganization(userId);
      if (!organization) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      const { areaId } = req.params;
      const existingArea = await this.areasRepository.getAreaById(
        areaId,
        organization.id
      );

      if (!existingArea) {
        return res
          .status(404)
          .json({ error: "Area not found", success: false });
      }

      // Block structural changes in root area
      if (existingArea.is_root_area && req.body.parent_area_id !== undefined) {
        return res.status(400).json({
          error: "The root area cannot be moved to another parent area.",
          success: false,
        });
      }

      if (
        !(await this._requireAreaWriteAccess(res, organization, areaId, userId))
      ) {
        return;
      }

      const {
        area_name,
        slug,
        description,
        properties,
        active,
        parent_area_id,
      } = req.body;

      const updates = {};

      if (area_name !== undefined) {
        updates.area_name = area_name.trim();
      }

      if (description !== undefined) {
        updates.description = description?.trim() || null;
      }

      if (properties !== undefined) {
        updates.properties = this._ensurePropertiesShape(properties);
      }

      if (active !== undefined) {
        updates.active = active;
      }

      if (parent_area_id !== undefined) {
        if (parent_area_id === existingArea.id) {
          return res.status(400).json({
            error: "An area cannot be its own parent",
            success: false,
          });
        }
        if (parent_area_id) {
          await this._getParentArea(organization.id, parent_area_id);
        }
        updates.parent_area_id = parent_area_id || null;
      }

      if (slug !== undefined || updates.area_name) {
        const baseSlug = this._normalizeSlug(
          updates.area_name || existingArea.area_name,
          slug
        );
        if (!baseSlug) {
          return res
            .status(400)
            .json({ error: "Invalid slug", success: false });
        }

        const finalSlug = await this._ensureUniqueSlug(
          organization.id,
          baseSlug,
          existingArea.slug
        );
        updates.slug = finalSlug;
      }

      const updatedArea = await this.areasRepository.updateArea(
        areaId,
        organization.id,
        updates
      );

      res.status(200).json({
        data: updatedArea,
        message: "Area updated successfully",
        status: "OK",
      });
    } catch (error) {
      console.error("Error updating area:", error);
      return next(fromUnknown(error));
    }
  }

  async deleteArea(req, res, next) {
