  buildUniqueConflictPayload,
  getUniqueFieldFromPgError,
} = require("@/modules/users/utils/unique-conflicts");

const PROJECT_MEMBER_ROLES = [
  "PROJECT_MANAGER",
  "CONTRIBUTOR",
  "COMMENTER",
  "VIEWER",
];
const MAX_SUPER_ADMINS = 3;

class OrganizationMembersController extends OrganizationsBaseController {
  constructor() {
    super();
    this.areasRepository = areasRepository;
  }

  async _ensureCanManageMembers(currentOrg, res) {
    if (
      !this._ensureOrgPermission(
        currentOrg,
        this._orgPermissions.MANAGE_MEMBERS,
        res
      )
    ) {
      return false;
    }
    return true;
  }

  async _ensureSuperAdminLimit(orgId, nextRole, res) {
    if (nextRole !== ORG_ROLES.SUPER_ADMIN) return true;
    const total = await this.organizationsRepository.countActiveMembersByRole(
      orgId,
      ORG_ROLES.SUPER_ADMIN
    );
    if (total >= MAX_SUPER_ADMINS) {
      res.status(400).json({
        error: `Limit of ${MAX_SUPER_ADMINS} super admins per workspace reached`,
      });
      return false;
    }
    return true;
  }

  _resolveProjectMemberRole(rawRole) {
    if (!rawRole || typeof rawRole !== "string") {
      return "CONTRIBUTOR";
    }
    return rawRole.trim().toUpperCase();
  }

  _mapProjectRoleToAreaRole(projectRole) {
    const normalizedRole = this._resolveProjectMemberRole(projectRole);
    if (normalizedRole === "PROJECT_MANAGER") return ORG_ROLES.ADMIN;
    if (normalizedRole === "CONTRIBUTOR") return ORG_ROLES.MEMBER;
    return ORG_ROLES.GUEST;
  }

  /**
   * Update a member's role in the organization
   * @param {Request & AuthenticatedRequest} req
   * @param {Response} res
   * @returns {Promise<void|Response>}
   */
  async updateMemberRole(req, res) {
    try {
      const authUserId = this._validateAuthentication(req, res);
      if (!authUserId) return;

      const { memberId } = req.params;
      const { role } = req.body;

      const currentOrg = await this._getUserOrganization(authUserId);
      if (!currentOrg) {
        return res.status(404).json({ error: "Organization not found" });
      }

      if (!(await this._ensureCanManageMembers(currentOrg, res))) {
        return;
      }

      if (!(await this._ensureSuperAdminLimit(currentOrg.id, role, res))) {
        return;
      }

      if (currentOrg.user_id === memberId) {
        return res
          .status(400)
          .json({ error: "Cannot change the organization owner's role" });
      }

      await this.organizationsRepository.updateMemberRole(
        currentOrg.id,
        memberId,
        role
      );

      res.status(200).json({
        data: { role },
        message: "Role updated successfully",
        status: "OK",
      });
    } catch (error) {
      console.error("Error updating member role:", error);
      res.status(500).json({ error: "Error updating member role" });
    }
  }

  /**
   * Remove a member from the organization
   * @param {Request & AuthenticatedRequest} req
   * @param {Response} res
   * @returns {Promise<void|Response>}
   */
  async removeMember(req, res, next) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const { memberId } = req.params;

      const currentOrg = await this._getUserOrganization(userId);
      if (!currentOrg) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      if (!(await this._ensureCanManageMembers(currentOrg, res))) {
        return;
      }

      if (String(currentOrg.user_id) === String(memberId)) {
        return res.status(400).json({
          error: "Cannot remove the organization owner",
          success: false,
        });
      }

      // ADMIN/SUPER_ADMIN must always keep their org-level record.
      // They need to be demoted first before removal.
      const targetMember =
        await this.organizationsRepository.getOrganizationMember(
          currentOrg.id,
          memberId
        );
      if (
        targetMember &&
        ["ADMIN", "SUPER_ADMIN"].includes(targetMember.role)
      ) {
        return res.status(400).json({
          error:
            "Cannot remove an administrator. Change role to MEMBER before removing.",
          success: false,
        });
      }

      const removed =
        await this.organizationsRepository.removeOrganizationMember(
          currentOrg.id,
          memberId
        );
      if (!removed) {
        return res
          .status(404)
          .json({ error: "Member not found", success: false });
      }

      res.status(200).json({
        data: removed,
        message: "Member removed successfully",
        status: "OK",
      });
    } catch (error) {
      console.error("Error removing member:", error);
      return next(fromUnknown(error));
    }
  }

  /**
   * Get all members of the organization
   * @param {Request & AuthenticatedRequest} req
   * @param {Response} res
   * @returns {Promise<void|Response>}
   */
  async getMembers(req, res) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const currentOrg = await this._getUserOrganization(userId);
      if (!currentOrg) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      if (
        !this._ensureOrgPermission(
          currentOrg,
          this._orgPermissions.VIEW_MEMBER_DIRECTORY,
          res
        )
      ) {
        return;
      }

      const members = await this.organizationsRepository.getOrganizationMembers(
        currentOrg.id
      );

      res.status(200).json({
        count: members.length,
        count_by_role: members.reduce((acc, member) => {
          acc[member.role] = (acc[member.role] || 0) + 1;
          return acc;
        }, {}),
        count_by_status: members.reduce((acc, member) => {
          acc[member.status] = (acc[member.status] || 0) + 1;
          return acc;
        }, {}),
        list_org_members: members.map((member) => ({
          member_data: {
            activity: {
              areas: member.areas || [],
              last_login_at: member.last_login_at || null,
              notes_count: parseInt(member.notes_count, 10) || 0,
              projects: member.projects || [],
            },
            avatar_url: member.avatar_url || null,
            email: member.email,
            id: member.user_id,
            invited_by: member.invited_by
              ? {
                  avatar_url: member.inviter_avatar_url || null,
                  id: member.invited_by,
                  name: member.inviter_name,
                  username: member.inviter_username,
                }
              : null,
            membership: {
              created_at: member.created_at,
              role: member.role,
              status: member.status,
              updated_at: member.updated_at,
            },
            name: member.name,
            username: member.username,
          },
        })),
        organization_id: currentOrg.id,

        status: "OK",
      });
    } catch (error) {
      console.error("Error fetching members:", error);
      res
        .status(500)
        .json({ error: "Error fetching members", status: "ERROR" });
    }
  }

  /**
   * Invite a new member to the organization
   * @param {Request & AuthenticatedRequest} req
   * @param {Response} res
   * @returns {Promise<void|Response>}
   */
  async inviteMember(req, res) {
    try {
      const authUserId = this._validateAuthentication(req, res);
      if (!authUserId) return;

      const {
        email,
        role = ORG_ROLES.MEMBER,
        name,
        username,
        target_areas = [],
      } = req.body;

      const normalizedRole =
        typeof role === "string" ? role.trim().toUpperCase() : "";

      const currentOrg = await this._getUserOrganization(authUserId);
      if (!currentOrg) {
        return res.status(404).json({ error: "Organization not found" });
      }

      if (!(await this._ensureCanManageMembers(currentOrg, res))) {
        return;
      }

      if (
        !(await this._ensureSuperAdminLimit(currentOrg.id, normalizedRole, res))
      ) {
        return;
      }

      const isGlobalRole =
        normalizedRole === ORG_ROLES.ADMIN ||
        normalizedRole === ORG_ROLES.SUPER_ADMIN;

      const validTargetAreas = [];
      for (const tArea of target_areas) {
        if (!tArea.area_id) continue;
        const area = await this.areasRepository.getAreaById(
          tArea.area_id,
          currentOrg.id
        );
        if (!area)
          return res
            .status(404)
            .json({ error: `Area not found: ${tArea.area_id}` });

        const resolvedProjectRole = this._resolveProjectMemberRole(tArea.role);
        validTargetAreas.push({
          area_id: tArea.area_id,
          role: resolvedProjectRole,
        });
      }

      const pending = await this.organizationsRepository.checkExistingInvite(
        currentOrg.id,
        email
      );
      if (pending) {
        return res.status(400).json({
          error: "There is already a pending invite for this email",
        });
      }

      const existingUsers = await SearchUsersRepository.findByUsernameOrEmail(
        "",
        email
      );
      const targetUser = existingUsers.find((u) => u.email === email);

      if (targetUser) {
        const isMember = await this.organizationsRepository.isMember(
          currentOrg.id,
          targetUser.user_id
        );
        if (isMember) {
          return res.status(400).json({
            error: "This user is already a member of the organization",
          });
        }
      }

      const usedName = name.trim();
      const invite = await this.organizationsRepository.createOrgInvite(
        currentOrg.id,
        email,
        normalizedRole,
        authUserId,
        usedName,
        username || null,
        validTargetAreas
      );

      const inviter = await SearchUsersRepository.findById(authUserId);
      const inviterLocale = await getUserEmailLocale({ userId: authUserId });

      // Send the invite email
      const emailResult = await send_organization_invite(
        email,
        currentOrg.org_name,
        inviter.name || inviter.username,
        invite.invite_id,
        normalizedRole,
        inviterLocale
      );

      if (!emailResult.success) {
        console.warn("Failed to send invite email:", emailResult.error);
      }

      res.status(201).json({
        data: {
          email: invite.email,
          expires_at: invite.expires_at,
          invite_id: invite.invite_id,
          role: invite.role,
          target_areas: invite.target_areas,
        },
        message: "Invite sent successfully.",
        status: "OK",
      });
    } catch (error) {
      console.error("Error inviting member:", error);
      res.status(500).json({ error: "Error processing member" });
    }
  }

  /**
   * Public: load invite details for the accept-invite UI (token is the secret).
   * @param {Request} req
   * @param {Response} res
   * @returns {Promise<void|Response>}
   */
  async previewInvite(req, res) {
    try {
      let token = req.query.token;
      if (!token || typeof token !== "string") {
        return res.status(400).json({ error: "Token is required" });
      }

      // Extract the UUID part from the token to be forgiving of extra garbage characters (e.g. trailing quotes)
      const uuidMatch = token.match(
        /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i
      );
      if (!uuidMatch) {
        return res.status(400).json({ error: "Invalid token format" });
      }
      token = uuidMatch[0];

      const invite =
        await this.organizationsRepository.findOrgInviteByToken(token);
      if (!invite) {
        const diag =
          await this.organizationsRepository.findOrgInviteByTokenDiagnostic(
            token
          );
        if (!diag) return res.status(404).json({ error: "Invite not found" });
        if (diag.deleted)
          return res.status(410).json({ error: "This invite was canceled" });
        if (diag.invite_verified)
          return res
            .status(409)
            .json({ error: "This invite has already been used" });
        if (new Date(diag.expires_at) < new Date())
          return res.status(410).json({
            error:
              "This invite has expired. Ask the administrator for a new invite.",
          });
        return res.status(400).json({ error: "Invalid or expired invite" });
      }

      const existingUsers = await SearchUsersRepository.findByUsernameOrEmail(
        "",
        invite.email
      );
      const has_account = existingUsers.some((u) => u.email === invite.email);

      return res.status(200).json({
        data: {
          email: invite.email,
          expires_at: invite.expires_at,
          has_account,
          invited_name: invite.name || null,
          org_logo_url: invite.logo_url
            ? spacesService.getFileUrl(invite.logo_url)
            : null,
          org_name: invite.org_name,
          role: invite.role,
          target_areas: invite.target_areas || [],
        },
        status: "OK",
      });
    } catch (error) {
      console.error("Error previewing invite:", error);
      res.status(500).json({ error: "Error loading invite" });
    }
  }

  /**
   * Accept an organization invite
   * @param {Request & AuthenticatedRequest} req
   * @param {Response} res
   * @returns {Promise<void|Response>}
   */
  async acceptInvite(req, res) {
    try {
      let { token, name, username, password } = req.body;
      const authUserId = req.user?.userId;

      // Extract the UUID part from the token to be forgiving of extra garbage characters
      const uuidMatch = token.match(
        /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i
      );
      if (!uuidMatch) {
        return res.status(400).json({ error: "Invalid token format" });
      }
      token = uuidMatch[0];

      const invite =
        await this.organizationsRepository.findOrgInviteByToken(token);
      if (!invite) {
        const diag =
          await this.organizationsRepository.findOrgInviteByTokenDiagnostic(
            token
          );
        if (!diag) return res.status(404).json({ error: "Invite not found" });
        if (diag.deleted)
          return res.status(410).json({ error: "This invite was canceled" });
        if (diag.invite_verified)
          return res.status(409).json({
            error:
              "This invite has already been used. Please contact the administrator for a new invite.",
          });
        if (new Date(diag.expires_at) < new Date())
          return res.status(410).json({
            error:
              "This invite has expired. Ask the administrator for a new invite.",
          });
        return res.status(400).json({ error: "Invalid or expired invite" });
      }

      const existingUsers = await SearchUsersRepository.findByUsernameOrEmail(
        "",
        invite.email
      );
      const targetUser = existingUsers.find((u) => u.email === invite.email);

      let targetUserId;

      if (!targetUser) {
        // User doesn't exist, we must create them now
        if (!name || !username || !password) {
          return res.status(400).json({
            error:
              "Name, username and password are required to accept the invite and create your account",
          });
        }

        const usernameAvailability =
          await SearchUsersRepository.checkUniqueAvailability({
            username,
          });
        if (!usernameAvailability.username.available) {
          return res.status(409).json(buildUniqueConflictPayload("username"));
        }

        const saltRounds = parseInt(process.env.BCRYPT_SALT_ROUNDS, 10) || 12;
        const hashedPassword = await bcrypt.hash(password, saltRounds);

        const createdUser = await CreateUsersRepository.createUser({
          email: invite.email,
          name,
          password: hashedPassword,
          private_profile: false,
          username,
        });

        if (!createdUser || !createdUser[0]) {
          return res
            .status(500)
            .json({ error: "Failed to create user account" });
        }

        targetUserId = createdUser[0].user_id;
        await UserTokensRepository.verifyUserEmail(targetUserId);

        if (req.file && req.file.buffer) {
          try {
            const saveResult = await spacesService.uploadProfileImage(
              req.file.buffer,
              req.file.mimetype,
              targetUserId
            );
            if (saveResult.success) {
              await UserDataRepository.updateProfileImage(
                targetUserId,
                saveResult.key
              );
            }
          } catch (imageError) {
            console.error("Error uploading image:", imageError);
          }
        }
      } else {
        // User already exists
        targetUserId = targetUser.user_id;

        if (authUserId && authUserId !== targetUserId) {
          return res.status(403).json({
            error:
              "You are logged in with a different account than the invited one.",
          });
        }

        if (!targetUser.email_verified && password) {
          // Verify their email if it wasn't, perhaps update their account
          const saltRounds = parseInt(process.env.BCRYPT_SALT_ROUNDS, 10) || 12;
          const hashedPassword = await bcrypt.hash(password, saltRounds);
          await UserDataRepository.updateUserPassword(
            targetUserId,
            hashedPassword
          );
          await UserTokensRepository.verifyUserEmail(targetUserId);
        }
      }

      const isMember = await this.organizationsRepository.isMember(
        invite.organization_id,
        targetUserId
      );
      if (!isMember) {
        await this.organizationsRepository.addOrganizationMember(
          invite.organization_id,
          targetUserId,
          invite.role,
          "ACTIVE",
          invite.invited_by
        );
      }

      if (Array.isArray(invite.target_areas)) {
        for (const targetArea of invite.target_areas) {
          if (!targetArea.area_id) continue;

          const areaRole = this._mapProjectRoleToAreaRole(targetArea.role);
          const existingAreaMember = await this.areasRepository.getAreaMember(
            targetArea.area_id,
            invite.organization_id,
            targetUserId
          );

          if (!existingAreaMember) {
            await this.areasRepository.addAreaMember(
              targetArea.area_id,
              invite.organization_id,
              targetUserId,
              areaRole,
              invite.invited_by
            );
          }
        }
      }

      await this.organizationsRepository.verifyOrgInvite(invite.invite_id);

      const frontendBase = process.env.FRONTEND_URL || "http://localhost:3000";
      const homePath = `${frontendBase}/app/home`;

      const confirmEmail = await send_organization_invite_accepted(
        invite.email,
        invite.org_name,
        homePath
      );
      if (!confirmEmail.success) {
        console.warn(
          "Failed to send invite-accepted email:",
          confirmEmail.error
        );
      }

      res.status(200).json({
        data: {
          organization: {
            id: invite.organization_id,
            name: invite.org_name,
          },
          role: invite.role,
          target_areas: invite.target_areas || [],
        },
        message: "Account activated and invite accepted successfully!",
        status: "OK",
      });
    } catch (error) {
      console.error("Error accepting invite:", error?.message || error);
      const uniqueField = getUniqueFieldFromPgError(error);
      if (uniqueField) {
        return res.status(409).json(buildUniqueConflictPayload(uniqueField));
      }
      const clientMsg =
        error?.message &&
        !error.message.toLowerCase().includes("sql") &&
        !error.message.toLowerCase().includes("postgres")
          ? error.message
          : "Error accepting invite";
      res.status(500).json({ error: clientMsg });
    }
  }
  /**
   * Get all invites of the organization
   * @param {Request & AuthenticatedRequest} req
   * @param {Response} res
   * @returns {Promise<void|Response>}
   */
  async getPendingInvites(req, res) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const currentOrg = await this._getUserOrganization(userId);
      if (!currentOrg) {
        return res.status(404).json({ error: "Organization not found" });
      }

      if (!(await this._ensureCanManageMembers(currentOrg, res))) {
        return;
      }

      const invites = await this.organizationsRepository.getAllOrgInvites(
        currentOrg.id
      );

      res.status(200).json({
        data: invites,
        status: "OK",
      });
    } catch (error) {
      console.error("Error fetching invites:", error);
      res.status(500).json({ error: "Error fetching invites" });
    }
  }

  /**
   * Cancel a pending invite
   * @param {Request & AuthenticatedRequest} req
   * @param {Response} res
   * @returns {Promise<void|Response>}
   */
  async cancelInvite(req, res) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const { invite_id } = req.params;
      const currentOrg = await this._getUserOrganization(userId);
      if (!currentOrg) {
        return res.status(404).json({ error: "Organization not found" });
      }

      if (!(await this._ensureCanManageMembers(currentOrg, res))) {
        return;
      }

      const invite =
        await this.organizationsRepository.findOrgInviteByToken(invite_id);
      if (!invite) {
        return res.status(404).json({ error: "Invite not found" });
      }

      if (String(invite.organization_id) !== String(currentOrg.id)) {
        return res
          .status(403)
          .json({ error: "No permission to cancel this invite" });
      }

      await this.organizationsRepository.deleteOrgInvite(invite_id);

      res.status(200).json({
        message: "Invite canceled successfully",
        status: "OK",
      });
    } catch (error) {
      console.error("Error canceling invite:", error);
      res.status(500).json({ error: "Error canceling invite" });
    }
  }

  /**
   * Resend a pending invite
   * @param {Request & AuthenticatedRequest} req
   * @param {Response} res
   */
  async resendInvite(req, res) {
    try {
      const authUserId = this._validateAuthentication(req, res);
      if (!authUserId) return;

      const { invite_id } = req.params;
      const currentOrg = await this._getUserOrganization(authUserId);
      if (!currentOrg) {
        return res.status(404).json({ error: "Organization not found" });
      }

      if (!(await this._ensureCanManageMembers(currentOrg, res))) {
        return;
      }

      let invite =
        await this.organizationsRepository.findOrgInviteByToken(invite_id);
      if (!invite) {
        // Might be expired, let's try to fetch it anyway to resend
        const pending = await this.organizationsRepository.getPendingOrgInvites(
          currentOrg.id
        );
        invite = pending.find((i) => i.invite_id === invite_id);
        if (!invite) {
          return res.status(404).json({ error: "Invite not found" });
        }
      }

      if (String(invite.organization_id) !== String(currentOrg.id)) {
        return res.status(403).json({ error: "No permission" });
      }

      // Update expiration
      const updatedInvite =
        await this.organizationsRepository.resendOrgInvite(invite_id);

      const inviter = await SearchUsersRepository.findById(authUserId);
      const inviterLocale = await getUserEmailLocale({ userId: authUserId });

      const emailResult = await send_organization_invite(
        updatedInvite.email,
        currentOrg.org_name,
        inviter.name || inviter.username,
        updatedInvite.invite_id,
        updatedInvite.role,
        inviterLocale
      );

      if (!emailResult.success) {
        console.warn("Failed to resend invite email:", emailResult.error);
      }

      res.status(200).json({
        data: updatedInvite,
        message: "Invite resent successfully",
        status: "OK",
      });
    } catch (error) {
      console.error("Error resending invite:", error);
      res.status(500).json({ error: "Error resending invite" });
    }
  }

  /**
   * Bulk invite members
   * @param {Request & AuthenticatedRequest} req
   * @param {Response} res
   */
  async inviteMembersBulk(req, res) {
    try {
      const authUserId = this._validateAuthentication(req, res);
      if (!authUserId) return;

      const { invites } = req.body;

      const currentOrg = await this._getUserOrganization(authUserId);
      if (!currentOrg) {
        return res.status(404).json({ error: "Organization not found" });
      }

      if (!(await this._ensureCanManageMembers(currentOrg, res))) {
        return;
      }

      const inviter = await SearchUsersRepository.findById(authUserId);
      const inviterLocale = await getUserEmailLocale({ userId: authUserId });

      const results = {
        failed: [],
        successful: [],
      };

      for (const inviteData of invites) {
        const {
          email,
          role = ORG_ROLES.MEMBER,
          name,
          username,
          target_areas = [],
        } = inviteData;

        try {
          const normalizedRole =
            typeof role === "string" ? role.trim().toUpperCase() : "";

          const pending =
            await this.organizationsRepository.checkExistingInvite(
              currentOrg.id,
              email
            );
          if (pending) {
            throw new Error("Invite already pending");
          }

          const existingUsers =
            await SearchUsersRepository.findByUsernameOrEmail("", email);
          const targetUser = existingUsers.find((u) => u.email === email);
          if (targetUser) {
            const isMember = await this.organizationsRepository.isMember(
              currentOrg.id,
              targetUser.user_id
            );
            if (isMember) {
              throw new Error("Already a member");
            }
          }

          // Validate areas
          const validTargetAreas = [];
          for (const tArea of target_areas) {
            if (!tArea.area_id) continue;
            const area = await this.areasRepository.getAreaById(
              tArea.area_id,
              currentOrg.id
            );
            if (area) {
              const resolvedRole = this._resolveProjectMemberRole(tArea.role);
              validTargetAreas.push({
                area_id: tArea.area_id,
                role: resolvedRole,
              });
            }
          }

          const invite = await this.organizationsRepository.createOrgInvite(
            currentOrg.id,
            email,
            normalizedRole,
            authUserId,
            name?.trim() || null,
            username || null,
            validTargetAreas
          );

          await send_organization_invite(
            email,
            currentOrg.org_name,
            inviter.name || inviter.username,
            invite.invite_id,
            normalizedRole,
            inviterLocale
          );

          results.successful.push({ email, invite_id: invite.invite_id });
        } catch (err) {
          results.failed.push({ email, reason: err.message });
        }
      }

      res.status(201).json({
        data: results,
        message: "Bulk invite processed",
        status: "OK",
      });
    } catch (error) {
      console.error("Error in bulk invite:", error);
      res.status(500).json({ error: "Error processing bulk invites" });
    }
  }
}

module.exports = new OrganizationMembersController();

const { AppError, fromUnknown, ERROR_CODES } = require("@/errors");
const OrganizationsBaseController = require("./base-controller");
const spacesService = require("@/services/storage");
const areasRepository = require("@/modules/organizations/repositories/areas.repository");
const {
  normalizeOrganizationName,
  generateUniqueOrganizationName,
  orgDataResponse,
} = require("../normalizer");
const {
  ORG_ROLES,
} = require("@/modules/organizations/organization-role-policy");

/**
 * Controller for organization management.
 * Handles organization lifecycle, branding assets, and organization projects.
 */
class OrganizationsController extends OrganizationsBaseController {
  /**
   * Initialize controller dependencies.
   */
  constructor() {
    super();
    this.areasRepository = areasRepository;
  }

  /**
   * Generate a unique area slug inside an organization.
   * @param {string|number} organizationId - Organization identifier
   * @param {string} slugBase - Base slug to test
   * @returns {Promise<string|null>} Unique slug or null when base is empty
   */
  async _generateUniqueAreaSlug(organizationId, slugBase) {
    if (!slugBase) {
      return null;
    }

    const existingSlugs = await this.areasRepository.getMatchingSlugs(
      organizationId,
      slugBase
    );

    if (!existingSlugs.includes(slugBase)) {
      return slugBase;
    }

    let counter = 1;
    let candidate = `${slugBase}-${counter}`;
    while (existingSlugs.includes(candidate)) {
      counter += 1;
      candidate = `${slugBase}-${counter}`;
    }

    return candidate;
  }

  /**
   * Create the default area for a newly created organization.
   * @param {Object} organization - Newly created organization data
   * @param {string|number} createdBy - User id who creates the default area
   * @returns {Promise<void>}
   */
  async _createDefaultOrganizationArea(organization, createdBy) {
    const defaultName = "Area Central";
    const slugBase =
      organization.unique_name || normalizeOrganizationName(defaultName);
    try {
      const uniqueSlug = await this._generateUniqueAreaSlug(
        organization.id,
        slugBase
      );

      const newArea = await this.areasRepository.createArea({
        areaName: defaultName,
        createdBy,
        description: `Main area for organization ${organization.org_name}`,
        organizationId: organization.id,
        parentAreaId: null,
        properties: { system: true },
        slug: uniqueSlug || `${slugBase}-${organization.id}`,
      });

      await this.areasRepository.addAreaMember(
        newArea.id,
        organization.id,
        createdBy,
        ORG_ROLES.ADMIN,
        createdBy
      );
    } catch (error) {
      console.error("Error creating default organization area:", error);
      throw new Error("Failed to create the default central organization area");
    }
  }

  /**
   * Create a new organization for the authenticated user.
   * @param {Object} req - Express request object
   * @param {Object} res - Express response object
   * @returns {Object} JSON response with created organization data or error
   */
  async createOrganization(req, res, next) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const existingOrg = await this._getUserOrganization(userId);
      if (existingOrg) {
        return res.status(400).json({
          error: "User already has an organization. Use PUT to update it.",
          success: false,
        });
      }

      const {
        org_name,
        unique_name: providedUniqueName,
        logo_url,
        banner_url,
        description,
        settings,
      } = req.body;

      let unique_name;
      if (providedUniqueName) {
        unique_name = normalizeOrganizationName(providedUniqueName);
        if (!unique_name) {
          throw new Error(
            "Provided unique name is invalid after normalization"
          );
        }

        const existingNames =
          await this.organizationsRepository.getAvailableOrgNames(unique_name);
        if (existingNames.includes(unique_name)) {
          throw new Error(`Unique name '${unique_name}' is already in use`);
        }
      } else {
        unique_name = await generateUniqueOrganizationName(org_name);
      }

      const newOrganization = await this.organizationsRepository.createOrgs(
        userId,
        org_name.trim(),
        unique_name,
        logo_url || null,
        banner_url || null,
        description?.trim() || "Type description here...",
        settings?.default_timezone || "America/Sao_Paulo",
        settings?.default_locale || "en-US",
        settings?.country || null,
        settings || {}
      );

      await this._createDefaultOrganizationArea(newOrganization, userId);

      res.status(201).json({
        data: newOrganization,
        message: "Organization created successfully",
        status: "OK",
        success: true,
      });
    } catch (error) {
      console.error("Error creating organization:", error);
      return next(fromUnknown(error));
    }
  }

  /**
   * Get organization data for the authenticated user.
   * @param {Object} req - Express request object
   * @param {Object} res - Express response object
   * @returns {Object} JSON response with organization data or error
   */
  async getOrganization(req, res) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const organization = await this._getUserOrganization(userId);
      if (!organization) {
        return res.status(404).json({
          error: "Organization not found",
          message: "User does not have an organization yet",
          success: false,
        });
      }

      const formattedOrganization = {
        created_at: organization.created_at,
        deleted: organization.deleted,
        identity: {
          banner_url: organization.banner_url,
          description: organization.description,
          id: organization.id,
          logo_url: organization.logo_url,
          member_role: organization.member_role ?? null,
          org_name: organization.org_name,
          unique_name: organization.unique_name,
          user_id: organization.user_id,
        },
        owners: [
          {
            avatar_url: organization.avatar_url,
            email: organization.email,
            id: organization.user_id,
            name: organization.name,
            username: organization.username,
          },
        ],
        settings: organization.settings || {},
        updated_at: organization.updated_at,
      };

      res
        .status(200)
        .json({ organization_data: formattedOrganization, status: "OK" });
    } catch (error) {
      console.error("Error getting organization:", error);
      res
        .status(500)
        .json({ error: "Error getting organization", success: false });
    }
  }

  /**
   * Update organization basic data and settings.
   * @param {Object} req - Express request object
   * @param {Object} res - Express response object
   * @returns {Object} JSON response with updated organization data or error
   */
  async updateOrganization(req, res, next) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const {
        org_name,
        unique_name,
        logo_url,
        banner_url,
        description,
        settings,
      } = req.body;

      const currentOrg = await this._getUserOrganization(userId);
      if (!currentOrg) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      const P = this._orgPermissions;
      const body = req.body || {};
      const touchesBrand = [
        "org_name",
        "unique_name",
        "logo_url",
        "banner_url",
        "description",
        "settings",
      ].some((k) => Object.prototype.hasOwnProperty.call(body, k));

      if (
        touchesBrand &&
        !this._ensureOrgPermission(currentOrg, P.MANAGE_BRAND, res)
      )
        return;

      let updatedUniqueName = currentOrg.unique_name;

      if (org_name && org_name !== currentOrg.org_name) {
        updatedUniqueName = await generateUniqueOrganizationName(org_name);
      }

      if (unique_name && unique_name !== currentOrg.unique_name) {
        const normalizedName = normalizeOrganizationName(unique_name);
        const existingNames =
          await this.organizationsRepository.getAvailableOrgNames(
            normalizedName
          );

        if (existingNames.includes(normalizedName)) {
          throw new Error("Unique name is already in use");
        }
        updatedUniqueName = normalizedName;
      }

      const updatedSettings = settings
        ? { ...currentOrg.settings, ...settings }
        : currentOrg.settings;

      const updatedOrg = await this.organizationsRepository.updateOrg(
        currentOrg.id,
        userId,
        org_name?.trim() || currentOrg.org_name,
        updatedUniqueName,
        logo_url !== undefined ? logo_url : currentOrg.logo_url,
        banner_url !== undefined ? banner_url : currentOrg.banner_url,
        description !== undefined
          ? description?.trim()
          : currentOrg.description,
        updatedSettings,
        currentOrg.deleted
      );

      if (!updatedOrg) {
        return res.status(403).json({
          code: "ORG_FORBIDDEN",
          error: "Insufficient permissions to update organization",
          success: false,
        });
      }

      res.status(200).json({
        data: updatedOrg,
        message: "Organization updated successfully",
        status: "OK",
        success: true,
      });
    } catch (error) {
      console.error("Error updating organization:", error);
      if (error instanceof Error && /not found/i.test(error.message)) {
        return next(
          AppError.notFound(
            "Organization not found",
            ERROR_CODES.RESOURCE_NOT_FOUND
          )
        );
      }
      return next(fromUnknown(error));
    }
  }

  /**
   * Update organization properties only.
   * @param {Object} req - Express request object
   * @param {Object} res - Express response object
   * @returns {Object} JSON response with updated organization data or error
   */
  async updateOrganizationProperties(req, res) {
    try {
      return res.status(410).json({
        error:
          "Organization properties column has been removed. Use organization settings fields instead.",
        success: false,
      });
    } catch (error) {
      return res.status(500).json({
        error: "Error handling deprecated properties endpoint",
        success: false,
      });
    }
  }

  /**
   * Soft-delete the current user organization.
   * @param {Object} req - Express request object
   * @param {Object} res - Express response object
   * @returns {Object} JSON response with deleted organization data or error
   */
  async deleteOrganization(req, res) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const currentOrg = await this._getUserOrganization(userId);
      if (!currentOrg) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      if (
        !this._ensureOrgPermission(
          currentOrg,
          this._orgPermissions.MANAGE_ORG_LIFECYCLE,
          res
        )
      )
        return;

      const deletedOrg = await this.organizationsRepository.updateOrg(
        currentOrg.id,
        userId,
        currentOrg.org_name,
        currentOrg.unique_name,
        currentOrg.logo_url,
        currentOrg.banner_url,
        currentOrg.description,
        currentOrg.settings,
        true
      );

      if (!deletedOrg) {
        return res.status(403).json({
          code: "ORG_FORBIDDEN",
          error: "Insufficient permissions to delete organization",
          success: false,
        });
      }

      res.status(200).json({
        data: deletedOrg,
        message: "Organization deleted successfully",
        status: "OK",
        success: true,
      });
    } catch (error) {
      console.error("Error deleting organization:", error);
      res
        .status(500)
        .json({ error: "Error deleting organization", success: false });
    }
  }

  /**
   * Restore a soft-deleted organization for the authenticated user.
   * @param {Object} req - Express request object
   * @param {Object} res - Express response object
   * @returns {Object} JSON response with restored organization data or error
   */
  async restoreOrganization(req, res) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const organizations =
        await this.organizationsRepository.getOrgsByUserId(userId);
      const organization = organizations.find((org) => org.deleted);

      if (!organization) {
        return res.status(404).json({
          error: "No deleted organization found",
          success: false,
        });
      }

      const memberRole = await this.organizationsRepository.getMembershipRole(
        organization.id,
        userId
      );
      const orgWithRole = {
        ...organization,
        member_role: memberRole || ORG_ROLES.SUPER_ADMIN,
      };

      if (
        !this._ensureOrgPermission(
          orgWithRole,
          this._orgPermissions.MANAGE_ORG_LIFECYCLE,
          res
        )
      )
        return;

      const restoredOrg = await this.organizationsRepository.updateOrg(
        organization.id,
        userId,
        organization.org_name,
        organization.unique_name,
        organization.logo_url,
        organization.banner_url,
        organization.description,
        organization.settings,
        false
      );

      if (!restoredOrg) {
        return res.status(403).json({
          code: "ORG_FORBIDDEN",
          error: "Insufficient permissions to restore organization",
          success: false,
        });
      }

      res.status(200).json({
        data: restoredOrg,
        message: "Organization restored successfully",
        status: "OK",
        success: true,
      });
    } catch (error) {
      console.error("Error restoring organization:", error);
      res
        .status(500)
        .json({ error: "Error restoring organization", success: false });
    }
  }

  /**
   * Upload and update organization logo.
   * @param {Object} req - Express request object
   * @param {Object} res - Express response object
   * @returns {Object} JSON response with upload metadata or error
   */
  async uploadLogo(req, res) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      if (!req.file) {
        return res
          .status(400)
          .json({ error: "No file was uploaded", success: false });
      }

      const currentOrg = await this._getUserOrganization(userId);
      if (!currentOrg) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      if (
        !this._ensureOrgPermission(
          currentOrg,
          this._orgPermissions.MANAGE_BRAND,
          res
        )
      )
        return;

      const result = await spacesService.uploadOrganizationLogo(
        req.file.buffer,
        req.file.mimetype,
        currentOrg.id
      );

      if (!result.success) {
        return res
          .status(500)
          .json({ error: "Error saving logo", success: false });
      }

      const updatedOrg = await this.organizationsRepository.updateOrgLogo(
        currentOrg.id,
        result.key,
        userId
      );

      if (!updatedOrg) {
        return res.status(403).json({
          code: "ORG_FORBIDDEN",
          error: "Insufficient permissions to update logo",
          success: false,
        });
      }

      res.status(200).json({
        data: {
          organization: orgDataResponse(updatedOrg),
          upload: {
            filename: result.fileName,
            path: result.key,
            size: result.size,
          },
        },
        message: "Logo updated successfully",
        status: "OK",
        success: true,
      });
    } catch (error) {
      console.error("Error uploading logo:", error);
      res.status(500).json({ error: "Error uploading logo", success: false });
    }
  }

  /**
   * Upload and update organization banner.
   * @param {Object} req - Express request object
   * @param {Object} res - Express response object
   * @returns {Object} JSON response with upload metadata or error
   */
  async uploadBanner(req, res) {
    try {
      const userId = this._validateAuthentication(req, res);

      if (!userId) return;

      if (!req.file) {
        return res
          .status(400)
          .json({ error: "No file was uploaded", success: false });
      }

      const currentOrg = await this._getUserOrganization(userId);
      if (!currentOrg) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      if (
        !this._ensureOrgPermission(
          currentOrg,
          this._orgPermissions.MANAGE_BRAND,
          res
        )
      )
        return;

      const result = await spacesService.uploadOrganizationBanner(
        req.file.buffer,
        req.file.mimetype,
        currentOrg.id
      );

      if (!result.success) {
        return res
          .status(500)
          .json({ error: "Error saving banner", success: false });
      }

      const updatedOrg = await this.organizationsRepository.updateOrgBanner(
        currentOrg.id,
        result.key,
        userId
      );

      if (!updatedOrg) {
        return res.status(403).json({
          code: "ORG_FORBIDDEN",
          error: "Insufficient permissions to update banner",
          success: false,
        });
      }

      res.status(200).json({
        data: {
          organization: orgDataResponse(updatedOrg),
          upload: {
            filename: result.fileName,
            path: result.key,
            size: result.size,
          },
        },
        message: "Banner updated successfully",
        status: "OK",
        success: true,
      });
    } catch (error) {
      res.status(500).json({ error: "Error uploading banner", success: false });
    }
  }

  /**
   * List projects for the current user organization.
   * @param {Object} req - Express request object
   * @param {Object} res - Express response object
   * @returns {Object} JSON response with projects list or error
   */
  async organizationProjects(req, res) {
    try {
      const userId = this._validateAuthentication(req, res);
      if (!userId) return;

      const currentOrg = await this._getUserOrganization(userId);
      if (!currentOrg) {
        return res
          .status(404)
          .json({ error: "Organization not found", success: false });
      }

      const projects =
        await this.organizationsRepository.getOrganizationProjects(
          currentOrg.id
        );

      res.status(200).json({
        organization_id: currentOrg.id,
        projects: projects,
        status: "OK",
      });
    } catch (error) {
      console.error("Error getting organization projects:", error);
      res.status(500).json({
        error: "Error getting organization projects",
        status: "ERROR",
      });
    }
  }
}

