  hasAnyQueryKey,
} = require("@/utils/http/list-query");
const {
  PROJECTS_LIST_TRIGGER_KEYS,
  PROJECT_STAGES_LIST_TRIGGER_KEYS,
  PROJECT_NOTES_LIST_TRIGGER_KEYS,
  PROJECT_COLLABORATORS_LIST_TRIGGER_KEYS,
