          }
          break;
        }

        case "update": {
          // Validar role
          if (!ASSIGNABLE_PROJECT_ROLES.includes(role)) {
            throw new Error(
              "Role inválido. Use 'project_manager', 'contributor', 'commenter' ou 'viewer'"
            );
