      const err = new Error(WORKSPACE_SHARE_DENIED.message);
      err.statusCode = 403;
      err.code = "WORKSPACE_SHARE_DENIED";
      throw err;
    }
    const result = await notesRepository.addCollaborator(noteId, collabUid);
    return {
      name,
      result: { noteId, updated: Boolean(result) },
      success: true,
    };
  }
}

