      args.projectId,
      userId,
      {
        title: args.title,
      }
    );
    return {
      name,
      result: {
        projectId: args.projectId,
        snapshot: oldProject
          ? { title: oldProject.title, type: "project_title" }
          : undefined,
        updated: Array.isArray(result) && result.length > 0,
      },
      success: true,
    };
  }
}

