class SearchUsersHandler {
  /**
   * Executes the tool logic to search for users.
   *
   * @param {Object} context - The execution context.
   * @param {string} context.userId - UUID of the user.
   * @param {Record<string, unknown>} context.args - Arguments passed by the LLM.
   * @param {string|null} context.organizationId - UUID of the organization.
   * @param {string} context.lang - Language code for errors.
   * @param {object} context.t - Translation dictionary.
   * @param {string} context.name - Name of the tool.
   * @returns {Promise<{name: string, result: object, success: boolean}>} The execution result.
   * @param { userId: string, args: Record<string, unknown>, organizationId: string|null, lang: string, t: object, name: string } context
   */
  async execute({ userId, args, organizationId, lang, t, name }) {
    const searchTerm = String(args.searchTerm || "").trim();
    if (!searchTerm) {
      throw new Error(t.searchUsersTermRequired);
    }
    const searchUsersRepository = require("@/modules/users/repositories/search-users.repository");
    const users = await searchUsersRepository.searchUsers(searchTerm, userId);
    const endpoint = (process.env.DO_SPACE_ENDPOINT || "").replace(/\/$/, "");
    const bucket = process.env.DO_SPACES_BUCKET_NAME || "wn-storage";
    const region = process.env.DO_SPACES_REGION || "sfo3";

    return {
      name,
      result: {
        users: users.map((u) => {
          let avatarUrl = null;
          if (u.avatar_url) {
            if (
              u.avatar_url.startsWith("http://") ||
              u.avatar_url.startsWith("https://")
            ) {
              avatarUrl = u.avatar_url;
            } else {
              avatarUrl = `${endpoint}/${bucket}/${u.avatar_url}`.replace(
                "digitaloceanspaces.com",
                `${region}.digitaloceanspaces.com`
              );
            }
          }
          return {
            avatar_url: avatarUrl,
            email: u.email,
            id: u.user_id,
            name: u.name,
            username: u.username,
          };
        }),
      },
      success: true,
    };
  }
}

module.exports = new SearchUsersHandler();

/**
 * @module weave-ai/services/agent-delegation.service
 * @description Handles the execution of the `delegate_to_agent` tool, creating an inner ReAct loop
 * by delegating the task to the chat-orchestrator service in "sub-agent" mode.
 */
const { randomUUID } = require("crypto");
// We require it dynamically or lazily if there's a circular dependency,
// since chat-functions requires this, and this requires chat-orchestrator, which requires chat-functions.
let chatOrchestratorService = null;

class AgentDelegationService {
  /**
   * Executes the delegation to a specialized agent.
   *
   * @param {string} userId - The user ID.
   * @param {string|null} organizationId - The organization ID.
   * @param {string} userLanguage - The user's language.
   * @param {string} agentId - The target agent ID to invoke.
   * @param {string} taskDescription - The description of the task.
   * @param {string} parentToolCallId - The ID of the tool call that initiated this delegation.
   * @param {Array<Object>} files - Uploaded files metadata, if they should be forwarded.
   * @returns {Promise<Object>} The result containing the final answer and sub-session ID.
   */
  async executeDelegateToAgent(
    userId,
    organizationId,
    userLanguage,
    agentId,
    taskDescription,
    parentToolCallId,
    files = []
  ) {
    if (!chatOrchestratorService) {
      chatOrchestratorService = require("./chat-orchestrator.service");
    }

    const subSessionId = randomUUID();
    const subRequestId = randomUUID();

    try {
      // Initiate a sub-agent session by calling the orchestrator
      const result = await chatOrchestratorService.orchestrateChat({
        files: [],
        onChunk: null,
        organizationId,
        // Do not forward raw file buffers by default to save bandwidth, unless requested. We can pass files if needed.
payload: {
          agentId: agentId,
          // The engine or orchestrator will resolve the appropriate model
allowEdit: false,

// Prevent destructive edits directly from sub-agents by default
allowWebSearch: true,


context: {},



isSubAgent: true,



message: taskDescription,


// To be tracked in the session's metadata
model: { name: "default", version: "latest" },

parentToolCallId,
          sessionId: subSessionId,
        },

requestId: subRequestId,

userId,

userLanguage, // We do not stream the sub-agent's inner monologue directly to the UI
      });

      return {
        result: {
          agentId: agentId,
          finalAnswer: result.response.content,
          subSessionId: result.sessionId,
        },
        success: true,
      };
    } catch (error) {
      console.error("[weave-ai/agent-delegation] Delegation failed:", error);
      return {
        error: error.message || "Failed to execute sub-agent delegation.",
        success: false,
      };
    }
  }
}

module.exports = new AgentDelegationService();

/**
 * @module weave-ai/services/chat-engine.service
 * @description Service responsible for communicating with the Weave Engine (Python microservice) via Redis RPC.
 * Manages the LLM prompt payload, streams responses, and tracks token usage.
 *
 * Dependencies:
 * - `@/services/queue/engine-rpc-connection`: Redis connection for sending RPC jobs.
 * - `../utils/chat-formatter.util`: To build context payloads.
 *
 * Used by:
 * - `weave-ai/services/chat-orchestrator.service.js`: To dispatch generation requests during the chat loop.
 */
const { randomUUID } = require("crypto");
const PlansRepository = require("@/modules/plans/repositories/plans.repository");
const engineRpcRedis = require("@/services/queue/engine-rpc-connection");
const {
  getEngineLlmRequestQueueRedisKey,
  getEngineLlmResponsePrefixRedisKey,
} = require("@/services/queue/queue-keys");
const chatFormatterUtil = require("../utils/chat-formatter.util");
const { getI18n } = require("../utils/weave-ai-i18n.util");

const Redis = require("ioredis");
const {
  getBlockingRedisOptions,
} = require("@/services/queue/blocking-redis-options");
const subscriberClient = new Redis(
  process.env.REDIS_URL,
  getBlockingRedisOptions()
);
const streamCallbacks = new Map();

subscriberClient.on("message", (channel, message) => {
  try {
    const callback = streamCallbacks.get(channel);
    if (callback) {
      const parsed = JSON.parse(message);
      if (parsed.chunk) {
        callback(parsed.chunk);
      }
    }
  } catch (e) {}
});

const ENGINE_CHAT_TIMEOUT_SECONDS = Number.parseInt(
  process.env.WEAVE_ENGINE_CHAT_TIMEOUT_SECONDS || "75",
  10
);

class ChatEngineService {
  /**
   * Builds compact plan usage context for Weave Engine prompts.
   *
   * @param {string} userId - Authenticated user's ID.
   * @param {string|null} [organizationId=null] - User's current organization ID.
   * @returns {Promise<Record<string, unknown>|null>} Plan usage context object or null.
   */
  async buildPlanUsageContext(userId, organizationId = null) {
    try {
      const [effectivePlan, usageRecord] = await Promise.all([
        PlansRepository.getEffectivePlanByUserId(userId),
        PlansRepository.getPlanUsage(userId, organizationId),
      ]);

      if (!effectivePlan && !usageRecord) {
        return null;
      }

      const planDetails = effectivePlan?.plan_details || {};
      const usageDetails = usageRecord?.usage_details || {};

      const aiEnabled = Boolean(
        chatFormatterUtil.getNestedValue(planDetails, "weave_ai.enabled")
      );
      const monthlyMessagesLimit = chatFormatterUtil.getNestedValue(
        planDetails,
        "weave_ai.config.monthly_messages"
      );
      const monthlyMessagesUsed = chatFormatterUtil.getNestedValue(
        usageDetails,
        "monthly_cycle.weave_ai.messages_sent"
      );
      const monthlyTokensUsed = chatFormatterUtil.getNestedValue(
        usageDetails,
        "monthly_cycle.weave_ai.tokens_estimated"
      );

      return {
        plan: {
          id: effectivePlan?.plan_id || null,
          name: effectivePlan?.plan_name || null,
          subscriberType: effectivePlan?.subscriber_type || null,
        },
        usage: {
          periodEnd:
            chatFormatterUtil.getNestedValue(
              usageDetails,
              "monthly_cycle.current_period_end"
            ) || null,
          periodStart:
            chatFormatterUtil.getNestedValue(
              usageDetails,
              "monthly_cycle.current_period_start"
            ) || null,
          weaveAi: {
            aiEnabled,
            monthlyMessagesLimit: Number.isFinite(Number(monthlyMessagesLimit))
              ? Number(monthlyMessagesLimit)
              : null,
            monthlyMessagesUsed: Number.isFinite(Number(monthlyMessagesUsed))
              ? Number(monthlyMessagesUsed)
              : null,
            monthlyTokensUsed: Number.isFinite(Number(monthlyTokensUsed))
              ? Number(monthlyTokensUsed)
              : null,
          },
        },
      };
    } catch (error) {
      console.error("[weave-ai/chat] failed to fetch plan usage context", {
        code: error?.code || null,
        message: error?.message || String(error),
      });
      return null;
    }
  }

  /**
   * Sends chat payload to engine queue and awaits response via Redis RPC.
   * Supports streaming chunks via a secondary Redis pub/sub channel.
   *
   * @param {object} payload - Job payload to send to engine queue.
   * @param {string} [requestId=randomUUID()] - Stable request UUID for idempotency.
   * @param {Function} [onChunk] - Optional callback to handle streaming text chunks.
   * @returns {Promise<{data: object, latencyMs: number, requestId: string}>} Parsed engine response data structure.
   */
  async requestEngineChat(payload, requestId = randomUUID(), onChunk) {
    const startedAt = Date.now();
    const requestQueueKey = getEngineLlmRequestQueueRedisKey();
    const responseQueueKey = `${getEngineLlmResponsePrefixRedisKey()}:${requestId}`;
    const lang = payload.userLanguage || "pt";
    const t = getI18n(lang);
    const streamChannel = `stream:${requestId}`;

    if (onChunk) {
      streamCallbacks.set(streamChannel, onChunk);
      await subscriberClient.subscribe(streamChannel);
    }

    const job = {
      attempts: 0,
      createdAt: new Date().toISOString(),
      payload,
      requestId,
      responseQueueKey,
      taskType: "chat_v2_process",
    };

    await engineRpcRedis.lpush(requestQueueKey, JSON.stringify(job));

    try {
      const queueResult = await engineRpcRedis.blpop(
        responseQueueKey,
        ENGINE_CHAT_TIMEOUT_SECONDS
      );
      if (!queueResult) {
        await engineRpcRedis.del(responseQueueKey);
        const timeoutError = new Error(t.engineTimeout);
        timeoutError.code = "ENGINE_TIMEOUT";
        timeoutError.requestId = requestId;
        timeoutError.statusCode = 504;
        throw timeoutError;
      }

      const [, rawResponsePayload] = queueResult;
      await engineRpcRedis.del(responseQueueKey);

      let parsedResponse;
      try {
        parsedResponse = JSON.parse(rawResponsePayload);
      } catch {
        const parseError = new Error(t.engineInvalidResponse);
        parseError.code = "ENGINE_INVALID_RESPONSE";
        parseError.statusCode = 502;
        throw parseError;
      }

      if (!parsedResponse?.success) {
        const engineErrorPayload = chatFormatterUtil.extractEngineErrorPayload(
          parsedResponse?.error,
          lang
        );
        const engineError = new Error(engineErrorPayload.message);
        engineError.code = engineErrorPayload.code;
        engineError.statusCode = 502;
        throw engineError;
      }

      return {
        data: parsedResponse.data || {},
        latencyMs: Date.now() - startedAt,
        requestId,
      };
    } finally {
      if (onChunk) {
        streamCallbacks.delete(streamChannel);
        subscriberClient.unsubscribe(streamChannel).catch(() => {});
      }
    }
  }
}

module.exports = new ChatEngineService();

/**
 * @module weave-ai/services/chat-functions.service
 * @description Service responsible for executing tools/functions requested by the LLM.
 *
 * Dependencies:
 * - `../handlers/tool-registry`: To dynamically resolve tool names to their handler implementations.
 * - `../utils/weave-ai-i18n.util`: For localized error messages if a function is not supported.
 *
 * Used by:
 * - `weave-ai/services/chat-orchestrator.service.js`: During the ReAct loop to execute functions returned by the engine.
 */
const notesRepository = require("@/modules/notes/notes.repository");
const projectsReadRepository = require("@/modules/projects/repositories/projects-read.repository");
const projectsUpdateRepository = require("@/modules/projects/repositories/projects-update.repository");
const workspaceUserScopeRepository = require("@/modules/users/repositories/workspace-user-scope.repository");
const chatAccessUtil = require("../utils/chat-access.util");
const chatFormatterUtil = require("../utils/chat-formatter.util");
const { markdownToBlocks } = require("../utils/markdown-to-blocks.util");
const { NOTE_STATUS } = require("@/utils/patterns/product-patterns");
const { WORKSPACE_SHARE_DENIED } = require("@/utils/workspace-share-guard");
const {
  normalizeBlocksTree,
  newBlockId,
} = require("@/modules/notes/block-normalizer");
const {
  enqueueNoteEmbeddingJob,
} = require("@/services/queue/queue-controller");
const { getI18n } = require("../utils/weave-ai-i18n.util");

class ChatFunctionsService {
  /**
   * Execute a single authorized tool/function call.
   *
   * @param {string} userId - The ID of the authenticated user.
   * @param {{name: string, arguments?: Record<string, unknown>}} functionCall - The tool execution details.
   * @param {string|null} [organizationId=null] - Optional organization ID scope for the call.
   * @param {string} [lang="pt"] - User language for error translations.
   * @returns {Promise<{name: string, success: boolean, result?: object}>} Result of the tool execution.
   */
  async executeFunctionCall(
    userId,
    functionCall,
    organizationId = null,
    lang = "en-US",
    files = []
  ) {
    const t = getI18n(lang);
    const name = String(functionCall?.name || "");
    const args =
      functionCall?.arguments && typeof functionCall.arguments === "object"
        ? functionCall.arguments
        : {};

    const registry = require("../handlers/tool-registry");
    const handler = registry.getHandler(name);

    if (!handler) {
      const error = new Error(
        typeof t.functionNotSupported === "function"
          ? t.functionNotSupported(name)
          : t.functionNotSupported
      );
      error.code = "CHAT_FUNCTION_NOT_SUPPORTED";
      error.statusCode = 400;
      throw error;
    }

    return await handler.execute({
      args,
      files,
      lang,
      name,
      organizationId,
      t,
      toolCallId: functionCall?.id,
      userId,
    });
  }

  /**
   * Executes all function calls from engine response.
   *
   * @param {string} userId - The ID of the authenticated user.
   * @param {Array<{name: string, arguments?: Record<string, unknown>}>} functionCalls - Array of tool execution details.
   * @param {string|null} [organizationId=null] - Optional organization ID scope for the calls.
   * @param {string} [lang="pt"] - User language for error translations.
   * @param {Function} [onChunk=null] - Callback to stream real-time execution state.
   * @returns {Promise<Array<object>>} Results of all tool executions.
   */
  async executeFunctionCalls(
    userId,
    functionCalls = [],
    organizationId = null,
    lang = "en-US",
    onChunk = null,
    files = []
  ) {
    const results = [];
    for (const functionCall of functionCalls) {
      if (onChunk) {
        onChunk({
          arguments: functionCall?.arguments,
          id: functionCall?.id,
          name: functionCall?.name,
          type: "tool_call_start",
        });
      }
      try {
        const execution = await this.executeFunctionCall(
          userId,
          functionCall,
          organizationId,
          lang,
          files
        );
        results.push(execution);
        if (onChunk) {
          onChunk({
            id: functionCall?.id,
            result: execution.result || execution,
            type: "tool_call_result",
          });
        }
      } catch (error) {
        console.warn(
          `[weave-ai/chat] Tool execution failed for ${functionCall?.name}:`,
          error?.message
        );
        results.push({
          error: error?.message || String(error),
          name: functionCall?.name || "unknown",
          success: false,
        });
        if (onChunk) {
          onChunk({
            id: functionCall?.id,
            result: { error: error?.message || String(error) },
            type: "tool_call_result",
          });
        }
      }
    }
    return results;
  }
}

module.exports = new ChatFunctionsService();
